/**
 * checkApplication with the call's type beside the candidates: the most
 * specific candidate's return type, or, for a tie among declarations without
 * static parameters that fit the call without coercion, in a family with no
 * declaration with static parameters, the intersection of the tied
 * candidates' return types. Such a tie arises where the argument's static
 * type sits between closed traits whose overlap other declarations cover;
 * the declaration that runs is below every tied one, and its return type
 * below each of theirs by the Return Type Rule.
 */
def typedApplication(preCandidates: List[PreAppCandidate],
                     iargs: List[Expr],
                     context: Option[Type],
                     mOpName: Option[Op],
                     fallBackWithoutContext: Boolean)
                    (implicit errorFactory: ApplicationErrorFactory)
                     : Option[(List[AppCandidate], Type)] = {

  // Check all the checkable args and make sure they all have types.
  val args = partitionArgs(iargs).getOrElse(return None)
  typedApplicationOfChecked(preCandidates, iargs, args, context, mOpName, fallBackWithoutContext, true)
}

/**
 * typedApplication over its args checked without an expected type. With
 * `retry`, a call that no attempt keeps is tried by the argument retry
 * before the attempts' fallback.
 */
def typedApplicationOfChecked(preCandidates: List[PreAppCandidate],
                              iargs: List[Expr],
                              args: List[Either[Expr, FnExpr]],
                              context: Option[Type],
                              mOpName: Option[Op],
                              fallBackWithoutContext: Boolean,
                              retry: Boolean)
                             (implicit errorFactory: ApplicationErrorFactory)
                              : Option[(List[AppCandidate], Type)] = {

  // A candidate, with its declaration's arrow when it is compared on its
  // declared domain, and whether the promotion instantiated it.
  type Ranked = (AppCandidate, Option[ArrowType], Boolean)
  type Attempt = List[(Either[AppCandidate, OverloadingError], Option[ArrowType], Boolean)]
  def moreSpecific(a: Ranked, b: Ranked) = moreSpecificCandidate(a._1, b._1, a._2, b._2, a._3, b._3)
  def isUnion(sarg: StaticArg) = sarg match {
    case STypeArg(_, false, _: UnionType) => true
    case _ => false
  }
  def generic(pc: PreAppCandidate) = getStaticParams(pc.arrow).exists(!_.isLifted)

  // Filter the overloadings that are applicable, by subtyping or with
  // coercion. A candidate without static parameters is checked alike in
  // every attempt, so it is checked once.
  val plain = scala.collection.mutable.Map[Int, (Either[AppCandidate, OverloadingError], Option[ArrowType], Boolean)]()
  def applicable(ctx: Option[Type], coerce: Boolean): Attempt = preCandidates.zipWithIndex.map { case (pc, i) =>
    if (getStaticParams(pc.arrow).isEmpty)
      plain.getOrElseUpdate(i, (checkApplicable(pc, ctx, args, mOpName, coerce), None, false))
    else checkApplicable(pc, ctx, args, mOpName, coerce) match {
      case Left(c) if !coerce && c.sargs.exists(isUnion) =>
        checkApplicable(pc, ctx, args, mOpName, false, Some(c.sargs.filter(!_.isLifted))) match {
          case Left(promoted) => (Left(promoted), Some(pc.arrow), true)
          case _ => (Left(c), None, false)
        }
      case Left(c) if coerce && generic(pc) => (Left(c), Some(pc.arrow), false)
      case e => (e, None, false)
    }
  }
  def candidatesOf(es: Attempt): List[Ranked] = es.collect { case (Left(c), d, p) => (c, d, p) }
  // A coercion the call needs, not one the promotion introduced.
  def counted(c: Ranked) = !c._3 && c._1.args.exists(_.isInstanceOf[CoercionInvocation])
  // An attempt by subtyping holds the candidates that fit the call without a
  // coercion it needs; an attempt with coercion holds all it finds.
  def holds(es: Attempt, coerce: Boolean) =
    if (coerce) candidatesOf(es).nonEmpty else candidatesOf(es).exists(!counted(_))
  def paramTypes(c: Ranked) = zipWithDomain(c._1.args, c._1.arrow.getDomain).map(_._2)
  def sameTypes(a: List[Type], b: List[Type]) =
    a.size == b.size && a.zip(b).forall(p => Formula.isTrue(analyzer.equivalent(p._1, p._2)))
  // The candidates no other candidate is more specific than.
  def minimal(cs: List[Ranked]) = cs.filter(c => !cs.exists(d => !(d eq c) && moreSpecific(d, c)))
  val groundFamily = preCandidates.forall(pc => getStaticParams(pc.arrow).isEmpty)
  // The type of a tie among declarations without static parameters that fit
  // the call as it is, in a family without static parameters.
  def tieType(top: List[Ranked]): Option[Type] =
    if (groundFamily && top.size > 1 && !top.exists(counted) &&
        top.forall(c => c._2.isEmpty && !c._3 && c._1.sargs.isEmpty) &&
        !top.forall(c => sameTypes(paramTypes(c), paramTypes(top.head))))
      Some(analyzer.meet(top.map(_._1.arrow.getRange)))
    else None
  def callType(cs: List[Ranked]): Type =
    (if (groundFamily) tieType(minimal(cs)) else None).getOrElse(cs.sortWith(moreSpecific).head._1.arrow.getRange)
  def kept(es: Attempt, coerce: Boolean) = holds(es, coerce) && context.forall(c =>
    coercions.substitutableFor(callType(candidatesOf(es)), c))
  // Each attempt: whether it is given the context, whether it coerces, and
  // the attempt itself.
  val attempts: List[(Boolean, Boolean, () => Attempt)] =
    if (context.isDefined)
      List((false, false, () => applicable(None, false)), (true, false, () => applicable(context, false)),
           (true, true, () => applicable(context, true)), (false, true, () => applicable(None, true)))
    else List((true, false, () => applicable(None, false)), (true, true, () => applicable(None, true)))
  val tried = attempts.to(LazyList).map { case (withContext, coerce, a) => (withContext, coerce, a()) }
  val keptAttempt = tried.find { case (_, coerce, a) => kept(a, coerce) }
  if (keptAttempt.isEmpty && retry)
    retypedApplication(preCandidates, iargs, args, context, mOpName, fallBackWithoutContext).
      foreach(r => return Some(r))
  val es = keptAttempt.map(_._3).getOrElse {
    // No attempt is kept: of the attempts with the context, or for a call
    // written f(x) of those without it, the first that holds a candidate,
    // whatever its result, and otherwise the first.
    val from = tried.filter(_._1 != (fallBackWithoutContext && context.isDefined))
    from.find { case (_, coerce, a) => holds(a, coerce) }.getOrElse(from.head)._3
  }
  val candidates = candidatesOf(es)
  val overloadingErrors = es.collect { case (Right(e), _, _) => e }

  // If there were no candidates, report errors.
  if (candidates.isEmpty) {
    errors.signal(errorFactory.makeApplicationError(overloadingErrors))
    return None
  }

  // Sort the arrows and instantiations to find the statically most
  // applicable. Then update each candidate's Overloading node.
  val sorted = candidates.sortWith(moreSpecific)

  // An overloading more specific than every candidate, whose size the call
  // does not fix, makes the call an error.
  val unfixed = overloadingErrors.filter {
    case NoContextError(_, _, Some(u)) => candidates.forall(c => moreSpecificCandidate(u, c._1, None, c._2, false, c._3))
    case _ => false
  }
  if (!unfixed.isEmpty) {
    errors.signal(errorFactory.makeApplicationError(unfixed))
    return None
  }

  // Ensure that the head is the most specific: the one candidate no other
  // is more specific than.
  val top = minimal(candidates)

  // A tie whose tied candidates differ only where the argument is a numeral:
  // each numeral is read as ZZ32 (ZZ64 or ZZ by magnitude), and the call
  // resolves as an argument of that type would, over every candidate: of
  // those the readings fit, the ones they fit without coercion first. At a
  // position whose declared type is a bare type parameter, a reading fits a
  // candidate compared on its declared arrow by that parameter's bound.
  def numeralTie(): Option[Ranked] = {
    val exprs = args.map(_.left.toOption)
    val n = exprs.size
    if (top.exists(c => paramTypes(c).size != n)) return None
    val tiedTypes = top.map(paramTypes)
    val differ = (0 until n).filter(i =>
      tiedTypes.exists(t => !Formula.isTrue(analyzer.equivalent(t(i), tiedTypes.head(i))))).toList
    if (differ.isEmpty || !differ.forall(i => exprs(i).exists(isNumeral))) return None
    val readings = (0 until n).toList.flatMap(i => exprs(i).filter(isNumeral).map(e => (i, numeralReading(List(e)))))
    if (readings.exists(_._2.isEmpty)) return None
    // The types a reading must fit at position i of a candidate.
    def targets(c: Ranked, i: Int, r: Type): List[Type] = {
      val bare = c._2.flatMap { d =>
        val sps = getStaticParams(d).filter(sp => !sp.isLifted && sp.getKind.isInstanceOf[KindType])
        zipWithDomain(args, d.getDomain).lift(i).map(_._2) match {
          case Some(v: VarType) => sps.find(_.getName == v.getName).map { sp =>
            object subst extends Walker {
              override def walk(node: Any): Any = node match {
                case w: VarType if w.getName == v.getName => r
                case _ => super.walk(node)
              }
            }
            toListFromImmutable(sp.getExtendsClause).map(b => subst(b).asInstanceOf[Type])
          }
          case _ => None
        }
      }
      bare.getOrElse(List(paramTypes(c)(i)))
    }
    def fitsBy(c: Ranked, rel: (Type, Type) => Boolean) = readings.forall { case (i, r) =>
      targets(c, i, r.get).forall(t => rel(r.get, t)) }
    val fits = candidates.filter(fitsBy(_, coercions.substitutableFor))
    val unconverted = fits.filter(fitsBy(_, (r, t) => isSubtype(r, t)))
    val among = if (unconverted.nonEmpty) unconverted else fits
    among.filter(c => !among.exists(d => !(d eq c) && moreSpecific(d, c))) match {
      case List(c) => Some(c)
      case _ => None
    }
  }

  val head: Option[Ranked] =
    if (top.size == 1) top.headOption
    // A tie among candidates that fit the call as it is, or among candidates
    // with one parameter type, keeps the sort's head.
    else if (top.isEmpty || !top.exists(counted) ||
             top.forall(c => sameTypes(paramTypes(c), paramTypes(top.head)))) sorted.headOption
    else numeralTie().orElse {
      signalAmbiguity(top.map(c => c._2.getOrElse(c._1.arrow)), args)
      return None
    }
  Some((head.toList.map(_._1) ++ sorted.filterNot(c => head.exists(_ eq c)).map(_._1),
        tieType(top).getOrElse(head.getOrElse(sorted.head)._1.arrow.getRange)))
}

/**
 * The argument retry, for a call that no attempt keeps, an argument of
 * which is itself a call whose static args it inferred with no expected
 * type. Each candidate in turn: each such argument is checked again with
 * the candidate's parameter type at its position as its expected type, that
 * type instantiated, where the candidate has static parameters, by the other
 * arguments (writesStaticArgs) and the call's expected type alone; the call is then checked
 * against that candidate alone, and the candidate counts when the call's
 * type converts to the expected type. Of the candidates that count, the one
 * more specific on its declared parameter types than every other is kept,
 * with its arguments. Otherwise the call is refused as it was.
 */
private def retypedApplication(preCandidates: List[PreAppCandidate],
                               iargs: List[Expr],
                               args: List[Either[Expr, FnExpr]],
                               context: Option[Type],
                               mOpName: Option[Op],
                               fallBackWithoutContext: Boolean)
                              (implicit errorFactory: ApplicationErrorFactory)
                               : Option[(List[AppCandidate], Type)] = {
  val positions = args.zipWithIndex.collect { case (Left(c), i) if retypable(c) => i }.toSet
  if (positions.isEmpty || iargs.size != args.size) return None
  val tryChecker = STypeCheckerFactory.makeTryChecker(this)

  // Get all the possible coercions from T_i to U.
  val tiCoercions = telts.map(checkSubstitutable(_, u, maybeArg))

  // Check that all of them were at least substitutable.
  if (tiCoercions.exists(_.isNone)) return None

  // If there's an arg, build the coercion. Otherwise just say yes: Some(None).
  val arg = maybeArg.getOrElse(return Some(None))
  val info = SExprInfo(NU.getSpan(arg), false, Some(u))
  Some(Some(SUnionCoercionInvocation(info, u, arg, telts, tiCoercions.map(_.get))))
}


private def checkCoercionTrait(t: Type,
                               u: TraitType,
                               maybeArg: Option[Expr])
                               : Option[Option[TraitCoercionInvocation]] = {
  // Make the dummy argument.
  val dummyArg = makeDummyFor(t)

  // Get a list of all the (coercion, arrow, inferred args, original arrow)
  // tuples that worked. The inferred args returned are only the unlifted
  // ones, as the lifted args are given in U.
  val liftedSargs = toListFromImmutable(u.getArgs)
  val allLiftedCoercions = getCoercionsTo(u)
  val coercionsAndArgs = allLiftedCoercions flatMap { liftedCoercion =>
    inferStaticParams(liftedCoercion._2, t, None) map { arrowAndSargs =>
      (liftedCoercion._1,
       arrowAndSargs._1,
       liftedSargs ++ arrowAndSargs._2, // Prepend the lifted static args.
       liftedCoercion._3)
    }
  }
  if (coercionsAndArgs.isEmpty) return None
  else if (maybeArg.isNone) return Some(None)
  val arg = maybeArg.get
  val argSpan = NU.getSpan(arg)

  // Build app candidates and sort them to find the SMA.
  val candidates = coercionsAndArgs.map { caa => {
    if (false) {
        AppCandidate(caa._2, caa._3, List(arg), None, None)
    } else {
        // Trying to fake an overloading to see if we can get the schema right
        // So far this breaks things, but why?
        val caa_ast = caa._1.ast
        AppCandidate(caa._2, caa._3, List(arg),
                Some(NF.makeOverloading(caa_ast.getInfo,
                     caa_ast.getUnambiguousName,
                     caa_ast.getHeader.getName,
                     Some(caa._2),
                     Some(caa._4))), None)
        }
    }
  }.toList.sortWith { (c1, c2) =>
    moreSpecificCandidate(c1, c2)(this)
  }
  val AppCandidate(bestArrow, bestSargs, _, bestOverload, bestFnl) = candidates.head
  val coercionId = makeCoercionId(u)

  // Make an overloading for each lifted coercion to U.
  val overloadings = coercionsAndArgs map { caa =>

    // Compute the name here using the import information, but use the span
    // from the original coercion decl.
    val coercionNameSpan = NU.getSpan(caa._1.ast.getUnambiguousName)
    val overloadingId = setSpan(coercionId, coercionNameSpan).asInstanceOf[Id]

    // Use coercionId as originalName -- no idea what the real name should be
    SOverloading(SSpanInfo(coercionNameSpan),
                 coercionId,
                 coercionId,
                 Some(caa._2),
                 Some(caa._4))
  }

  // Make a dummy functional ref.
  val fnRef = EF.makeFnRefHelpScala(argSpan,
                           false,
                           coercionId,
                           toJavaList(Nil),
                           toJavaList(overloadings),
                           toJavaList(overloadings),
                           bestOverload.get.getType,
                           bestOverload.get.getSchema)

  // Rewrite the FnRef so that it filters out dynamically unapplicable arrows.
  val newFnRef = rewriteApplicand(fnRef, candidates, true).asInstanceOf[FnRef]

  // Make the coercion invocation!
  Some(Some(STraitCoercionInvocation(SExprInfo(argSpan, false, Some(u)), arg, u, newFnRef)))
}

private def checkCoercionTuple(t: TupleType,
                               u: TupleType,
                               maybeArg: Option[Expr])
                               : Option[Option[TupleCoercionInvocation]] = {
  val (x@STupleType(_, xelts, xvar, _), y@STupleType(_, yelts, yvar, _)) = (t, u)

  // 1. X is not a subtype of Y.

      mOps: Option[(Op,Op)])(implicit analyzer: TypeAnalyzer): Option[(ArrowType, List[StaticArg])] = {

    val sparams = getStaticParams(fnType).filter(_.isLifted)
    if (sparams.isEmpty || fnType.getMethodInfo.isNone) return Some((fnType, Nil))

    // Builds a constraint given the arrow with inference variables.
    def makeConstraint(infArrow: ArrowType, map: Map[Op, Op]): CFormula = {
      // Get the type of the `self` arg and form selfArg <:? selfType
      val SMethodInfo(selfType, selfPosition) = infArrow.getMethodInfo.unwrap
      val tConstraint = getTypeAt(argType, selfPosition) match {
        case Some(selfArgType) => checkSubtype(selfArgType, selfType)
        case None => False
      }
      val oConstraint = mOps match {
        case Some((op, ov_op)) => 
          analyzer.equivalent(op, map.getOrElse(analyzer.normalize(ov_op), ov_op))
        case None => True
      }
      and(tConstraint, oConstraint)
    }

    // Do the inference.
    inferStaticParamsHelper(fnType, makeConstraint, true, false, true)
  }

  /**
   * Define an ordering relation on arrows with their instantiations. That is,
   * is candidate1 more specific than candidate2? A generic candidate may carry
   * its declared arrow, and is then compared on its declared domain: between
   * two candidates without coercion, by subtyping on declared domains; between
   * two with coercion, by that when it relates them one way, and otherwise by
   * the coercion chapter's order on their domains. The coercions the promotion
   * introduced into a promoted candidate are not counted.
   */
  def moreSpecificCandidate(candidate1: AppCandidate,
    candidate2: AppCandidate,
    declared1: Option[ArrowType] = None,
    declared2: Option[ArrowType] = None,
    promoted1: Boolean = false,
    promoted2: Boolean = false)(implicit coercions: CoercionOracle): Boolean = {

    val AppCandidate(SArrowType(_, domain1, range1, _, _, mi1), _, args1, _, _) = candidate1
    val AppCandidate(SArrowType(_, domain2, range2, _, _, mi2), _, args2, _, _) = candidate2

    // If these are dotted methods, add in the self type as an implicit first
    // parameter. The new domains will be a tuple of the form
    // `(selfType, domainType)`.
    val (newDomain1, newDomain2) = (mi1, mi2) match {
      case (Some(SMethodInfo(selfType1, -1)),
        Some(SMethodInfo(selfType2, -1))) =>
        (getDomainAndSelfType(candidate1.arrow),
          getDomainAndSelfType(candidate2.arrow))
      case _ => (domain1, domain2)
    }

    // Determine if a coercion occurred.
    val coercion1 = !promoted1 && args1.exists(_.isInstanceOf[CoercionInvocation])
    val coercion2 = !promoted2 && args2.exists(_.isInstanceOf[CoercionInvocation])
    lazy val d1 = declared1.getOrElse(candidate1.arrow)
    lazy val d2 = declared2.getOrElse(candidate2.arrow)

    // If one did not use coercions and the other did, the one without coercions
    // is more specific.
    (coercion1, coercion2) match {
      case (true, false) => false
      case (false, true) => true
      case (false, false) if declared1.isDefined || declared2.isDefined =>
        coercions.moreSpecificDeclared(d1, d2)
      case (true, true) if declared1.isDefined || declared2.isDefined =>
        if (coercions.moreSpecificDeclared(d1, d2)) true
        else if (coercions.moreSpecificDeclared(d2, d1)) false
        else coercions.moreSpecific(newDomain1, newDomain2)
      case _ => coercions.moreSpecific(newDomain1, newDomain2)
    }
  }

  /**
   * Determines if the given overloading is dynamically applicable.
   */
  def isDynamicallyApplicable(overloading: Overloading,
    bestArrow: ArrowType,
    unliftedSargs: List[StaticArg],
    liftedSargs: List[StaticArg])(implicit analyzer: TypeAnalyzer): Option[Overloading] = {

    val SOverloading(ovInfo, ovName, origName, Some(ovType), schema) = overloading
    var newOvType: ArrowType = ovType
    val bestArrowDomainAndSelfType = getDomainAndSelfType(bestArrow)

    // If unlifted static args, then instantiate the unlifted static params.
    if (!unliftedSargs.isEmpty)
      newOvType = staticInstantiation(unliftedSargs, newOvType)
        .getOrElse(return None).asInstanceOf[ArrowType]

    // If there were lifted, inferred static args, then instantiate those.
    if (!liftedSargs.isEmpty)
      newOvType = staticInstantiation(liftedSargs,
        newOvType,
        applyLifted = true,
        applyUnlifted = false)
        .getOrElse(return None).asInstanceOf[ArrowType]

    // If there are still some static params in it, then we can't infer them
    // so it's not applicable. If this is not a subtype of the best arrow, then
    // it cannot be picked at runtime.
    if (hasStaticParams(newOvType) ||
      !isSubtype(getDomainAndSelfType(newOvType),
        bestArrowDomainAndSelfType))
      return None

    Some(SOverloading(ovInfo, ovName, origName, Some(newOvType), schema))
  }
