import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.util.*;

// java Agg.java rec.jfr PATTERN...: samples in all, the top self frames, and per pattern the samples whose stack holds a frame matching it
public class Agg {
    public static void main(String[] a) throws Exception {
        Map<String, Integer> self = new HashMap<>();
        Map<String, Integer> incl = new LinkedHashMap<>();
        for (int i = 1; i < a.length; i++) incl.put(a[i], 0);
        int total = 0;
        try (RecordingFile rf = new RecordingFile(Path.of(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace();
                if (st == null || st.getFrames().isEmpty()) continue;
                total++;
                RecordedFrame top = st.getFrames().get(0);
                String k = top.getMethod().getType().getName() + "." + top.getMethod().getName();
                self.merge(k, 1, Integer::sum);
                Set<String> seen = new HashSet<>();
                for (RecordedFrame f : st.getFrames()) {
                    String m = f.getMethod().getType().getName() + "." + f.getMethod().getName();
                    for (String p : incl.keySet()) if (m.contains(p) && seen.add(p)) incl.merge(p, 1, Integer::sum);
                }
            }
        }
        System.out.println("samples " + total);
        self.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(15)
            .forEach(x -> System.out.printf("self %6d %5.1f%% %s%n", x.getValue(), 100.0 * x.getValue() / total, x.getKey()));
        for (Map.Entry<String, Integer> x : incl.entrySet())
            System.out.printf("incl %6d %5.1f%% %s%n", x.getValue(), 100.0 * x.getValue() / total, x.getKey());
    }
}
EOF
