import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.util.*;

// java Split.java rec.jfr: for the samples under PartialOrder, the frame just below the deepest PartialOrder frame
// (what it calls, or self) and the frame just above the outermost one (its caller)
public class Split {
    static String name(RecordedFrame f) { return f.getMethod().getType().getName() + "." + f.getMethod().getName() + ":" + f.getLineNumber(); }
    public static void main(String[] a) throws Exception {
        Map<String, Integer> callee = new HashMap<>(), caller = new HashMap<>();
        int n = 0;
        try (RecordingFile rf = new RecordingFile(Path.of(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample") || e.getStackTrace() == null) continue;
                List<RecordedFrame> fs = e.getStackTrace().getFrames();
                int lo = -1, hi = -1;
                for (int i = 0; i < fs.size(); i++) if (fs.get(i).getMethod().getType().getName().contains("PartialOrder")) { if (lo < 0) lo = i; hi = i; }
                if (lo < 0) continue;
                n++;
                callee.merge(lo == 0 ? "(self) " + name(fs.get(0)) : name(fs.get(lo - 1)), 1, Integer::sum);
                caller.merge(hi + 1 < fs.size() ? name(fs.get(hi + 1)) : "(top)", 1, Integer::sum);
            }
        }
        System.out.println("samples under PartialOrder " + n);
        callee.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(8).forEach(x -> System.out.println("callee " + x.getValue() + " " + x.getKey()));
        caller.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(10).forEach(x -> System.out.println("caller " + x.getValue() + " " + x.getKey()));
    }
}
EOF
