private val n = elems.length
// At i * n + j: 0 where lt(elems(i), elems(j)) is not read yet, 1 where it
// is false, 2 where it is true.
private val memo = new Array[Byte](n * n)
private var phase = 0
PartialOrderAudit.order(n)

/** Whether the element at i precedes the element at j. */
def precedes(i: Int, j: Int): Boolean =
  if (i == j || (elems(i).asInstanceOf[AnyRef] eq elems(j).asInstanceOf[AnyRef])) false
  else {
    val k = i * n + j
    val m = memo(k)
    if (m != 0) {
      // audit: the reused answer, computed again
      val again = lt(elems(i).asInstanceOf[T], elems(j).asInstanceOf[T])
      PartialOrderAudit.reuse(again == (m == 2), elems(i), elems(j))
      m == 2
    }
    else {
      PartialOrderAudit.read(phase, lt(elems(i).asInstanceOf[T], elems(j).asInstanceOf[T]))
      val r = lt(elems(i).asInstanceOf[T], elems(j).asInstanceOf[T])
      memo(k) = if (r) 2 else 1
      r
    }
  }

private def hasPredecessor(j: Int): Boolean = {
  var i = 0
  while (i < n) {
    if (precedes(i, j)) return true

      if (precedes(i, j)) return true
      i += 1
    }
    false
  }

  /** The elements that no other element precedes, in the order of xs. */
  lazy val minimal: List[T] = { phase = 1; val r =
    (0 until n).filterNot(hasPredecessor).map(elems(_).asInstanceOf[T]).toList; phase = 0; r }

  /** A linear extension of the order, otherwise in the order of xs. */
  lazy val linear: List[T] = { phase = 2
    val left = Array.fill(n)(true)
    // blocker(j): an element that precedes j, found among those left when j
    // was last read, or -1. The elements before it were read and do not
    // precede j, or had been taken.
    val blocker = Array.fill(n)(-1)
    def blocked(j: Int): Boolean = {
      if (blocker(j) >= 0 && left(blocker(j))) return true
      var i = blocker(j) + 1
      while (i < n) {
        if (left(i) && precedes(i, j)) { blocker(j) = i; return true }
        i += 1
      }
      blocker(j) = n
      false
    }
    val out = List.newBuilder[T]
    var taken = 0
    while (taken < n) {
      var pick = -1
      var j = 0
      while (pick < 0 && j < n) {
        if (left(j) && !blocked(j)) pick = j
        j += 1
      }
      if (pick < 0) pick = left.indexWhere(identity)
      left(pick) = false
      taken += 1
      out += elems(pick).asInstanceOf[T]
    }
    phase = 0
    out.result()
  }
}

object PartialOrderAudit {
  private val reads = new java.util.concurrent.atomic.AtomicLong
  private val reuses = new java.util.concurrent.atomic.AtomicLong
  private val differences = new java.util.concurrent.atomic.AtomicLong
  private val byPhase = Array.fill(6)(new java.util.concurrent.atomic.AtomicLong)
  private val sizes = new java.util.concurrent.ConcurrentHashMap[Int, java.util.concurrent.atomic.AtomicLong]
  def order(n: Int): Unit = sizes.computeIfAbsent(n, _ => new java.util.concurrent.atomic.AtomicLong).incrementAndGet()
  def read(phase: Int, r: Boolean): Unit = { reads.incrementAndGet(); byPhase(phase * 2 + (if (r) 1 else 0)).incrementAndGet() }
  def reuse(same: Boolean, a: Any, b: Any): Unit = {
    reuses.incrementAndGet()
    if (!same) { differences.incrementAndGet(); System.err.println("@@AUDIT difference: " + a + " / " + b) }
  }
  Runtime.getRuntime.addShutdownHook(new Thread(() =>
    { System.err.println("@@AUDIT PartialOrder reads=" + reads.get + " reuses=" + reuses.get + " differences=" + differences.get)
      System.err.println("@@AUDIT reads by phase (none/minimal/linear x false/true): " + byPhase.map(_.get).mkString(" "))
      val ks = new java.util.TreeMap[Int, java.util.concurrent.atomic.AtomicLong](sizes)
      System.err.println("@@AUDIT orders by size: " + ks.toString) }))
}

